Q=np.array(obs.meta['proprio']['now'][10:14])
POS=np.array(obs.meta['proprio']['now'][7:10])
seq=0

def execute(points, label='move', cameras=('practice_cam',), frames=False):
    global POS,seq
    a=np.array(points,dtype=float)
    if a.shape[1]==3: a=np.column_stack([a,np.tile(Q,(len(a),1))])
    # persist intended hardware targets before execution
    np.save(OUT/f'actions_{seq:04d}.npy',a)
    for i in range(0,len(a),190):
        res=r.submit('ee_pose',a[i:i+190],dt=.05,cameras=list(cameras),video='frames' if frames else 'none',video_fps=10,note=label)
        print('CALL',seq,i,'steps',res.meta.get('control_steps_chunk'),'plan',res.meta.get('plan'),'left',res.meta.get('time_left_s'),flush=True)
        res.save(str(OUT/f'run_{seq:04d}_{i}'))
        POS=np.array(res.meta['proprio']['now'][7:10])
    seq+=1
    return res

def line(a,b,speed=.07):
    n=max(1,int(np.ceil(np.linalg.norm(np.array(b)-a)/speed/.05)))
    return np.linspace(a,b,n+1)[1:].tolist()

def travel(p):
    p=np.array(p)
    a=POS.copy(); a[2]=max(.06,a[2])
    b=p.copy(); b[2]=a[2]
    return execute(line(POS,a)+line(a,b)+line(b,p)+[p.tolist()]*8,'travel')

def observe(name='obs',cameras=('canvas_cam','practice_cam','scene_cam','side_cam'),depth=False):
    o=r.get_obs(cameras=list(cameras),depth=depth); o.save(str(OUT/name)); print('TIME',o.meta.get('time_left_s'),flush=True); return o

def pixel(u,v,z=.018):
    return np.array([-.1+(512-v)*.227185/1024,(512-u)*.227185/1024,z])

print('READY',flush=True)
PY
